    if (!isParked(item)) return false;
    if (!SUPERSEDABLE_PARKS.includes(parkKindOf(item))) return false;
    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
